-- Reference database for the comparison of two PostgreSQL databases, node 3.
-- Generated by gen.py from the files in src/. Do not edit.
--
-- Usage:  psql -X -q -v ON_ERROR_STOP=1 -d <database> -f node3.sql
--
-- The script drops and creates the schemas ref_meta, num, typ, eqv, txt, nul,
-- key, dty, lob, str, rep, ver, dmp in the current database. The table
-- ref_meta.cases says, for each table, which case it belongs to and what a
-- comparison of node 1 and node 2 should report.

-- ======================================================================
-- 00_setup.sql
-- ======================================================================
-- Session settings, cleanup of an earlier run, extensions, schemas, roles and
-- the register of cases.
SET client_min_messages = warning;
SET client_encoding = 'UTF8';
SET TimeZone = 'UTC';
SET DateStyle = 'ISO, MDY';
SET IntervalStyle = 'postgres';
SET lc_monetary = 'C';
SET extra_float_digits = 1;
SET bytea_output = 'hex';
SET search_path = public;

DROP SCHEMA IF EXISTS ref_meta, num, typ, eqv, txt, nul, key, dty, lob, str, rep, ver, dmp CASCADE;
DROP SERVER IF EXISTS ace_ref_loopback CASCADE;
DO $$
DECLARE
	r record;
BEGIN
	FOR r IN SELECT oid FROM pg_largeobject_metadata WHERE oid BETWEEN 900000 AND 900999 LOOP
		PERFORM lo_unlink(r.oid);
	END LOOP;
END $$;

CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS hstore;
CREATE EXTENSION IF NOT EXISTS ltree;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS lo;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS postgres_fdw;

-- Two roles for the cases about privileges (L7, S8, S9). Roles belong to the
-- whole instance, so they are created once and kept.
DO $$
BEGIN
	IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'ace_ref_reader') THEN
		CREATE ROLE ace_ref_reader LOGIN;
	END IF;
	IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'ace_ref_other') THEN
		CREATE ROLE ace_ref_other NOLOGIN;
	END IF;
END $$;

CREATE SCHEMA ref_meta;  -- register of cases, the same on every node
CREATE SCHEMA num;       -- numeric and float
CREATE SCHEMA typ;       -- types and table definitions
CREATE SCHEMA eqv;       -- equal by the operator, different text
CREATE SCHEMA txt;       -- text output, session, encoding
CREATE SCHEMA nul;       -- NULL and row encoding
CREATE SCHEMA key;       -- keys and block bounds
CREATE SCHEMA dty;       -- other data types
CREATE SCHEMA lob;       -- oid columns and large objects
CREATE SCHEMA str;       -- table structure, visibility, replication design
CREATE SCHEMA rep;       -- repair
CREATE SCHEMA ver;       -- verdict
CREATE SCHEMA dmp;       -- dump / restore / pg_upgrade scenario

-- One line for each pair (case, table). The text in "expect" says what a
-- correct comparison of node 1 and node 2 should report for this table.
CREATE TABLE ref_meta.cases (
	case_id text NOT NULL,
	tbl     text NOT NULL,
	expect  text NOT NULL,
	PRIMARY KEY (case_id, tbl)
);

CREATE PROCEDURE ref_meta.reg(text, text, text)
LANGUAGE sql
AS $$ INSERT INTO ref_meta.cases VALUES ($1, $2, $3) $$;

-- ======================================================================
-- 80_three.sql
-- ======================================================================
-- Cases that need a third node (R4, U6) or another database encoding
-- (X3, X10). Node 3 can be a database with the LATIN1 encoding.

-- R4: three nodes.
CREATE TABLE rep.r04_three_nodes (id int PRIMARY KEY, v text);
INSERT INTO rep.r04_three_nodes VALUES (1, 'same');
INSERT INTO rep.r04_three_nodes VALUES (2, 'on n2 and n3'), (3, 'v3 of n3'), (4, 'only n3');
CALL ref_meta.reg('R4', 'rep.r04_three_nodes', 'row 2 is missing on n1 and is the same on n2 and n3: one INSERT into n1, not two. Row 3 has three versions. Row 4 only on n3');

-- U6 with three nodes: two donors for one NULL.
CREATE TABLE nul.u06_fix_nulls_three (id int PRIMARY KEY, a text);
INSERT INTO nul.u06_fix_nulls_three VALUES (1, 'from n3'), (2, 'same donor');
CALL ref_meta.reg('U6', 'nul.u06_fix_nulls_three', 'a repair that only fills NULLs, on three nodes: row 1 of n1 has two different donors (the choice must follow a stated rule), row 2 has one value');

-- X3: text that both a UTF8 and a LATIN1 database can hold.
CREATE TABLE txt.x03_encoding (id int PRIMARY KEY, v text);
INSERT INTO txt.x03_encoding VALUES (1, 'plain'), (2, U&'caf\00E9'), (3, U&'na\00EFve'), (4, U&'\00DCn\00EFc\00F6d\00E9'), (5, U&'\00A3 10 \00B1 1');
CALL ref_meta.reg('X3', 'txt.x03_encoding', 'match on all nodes, also when the database encodings differ (UTF8 / LATIN1)');
-- P14: a database restored with another encoding.
CALL ref_meta.reg('P14', 'txt.x03_encoding', 'a database restored with another encoding');

-- X10: text that a LATIN1 database cannot hold.
CREATE TABLE txt.x10_encoding_target (id int PRIMARY KEY, v text);
INSERT INTO txt.x10_encoding_target VALUES (1, 'plain');
CALL ref_meta.reg('X10', 'txt.x10_encoding_target', 'n1 and n2 match. Against a LATIN1 node 3: rows 2-4 only on n1; repair into n3 fails for rows 2, 3 (no equivalent in LATIN1) and is applied for row 4');

-- ======================================================================
-- 99_finish.sql
-- ======================================================================
-- Privileges of the test role and statistics.
GRANT USAGE ON SCHEMA ref_meta, num, typ, eqv, txt, nul, key, dty, lob, str, rep, ver, dmp TO ace_ref_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA ref_meta, num, typ, eqv, txt, nul, key, dty, lob, str, rep, ver, dmp TO ace_ref_reader;
ANALYZE;
